function validate([encoded]) {
  if (!Array.isArray(encoded) || encoded.length < 2 || encoded.length >= 100000) return 'encoded needs 2 to 99998 values.';
  if (encoded.length % 2 !== 0) return 'encoded must have an even length, since n is odd.';
  if (encoded.some(v => !Number.isInteger(v) || v < 0)) return 'Each value is a non-negative integer.';
  const n = encoded.length + 1;
  let first = 0;
  for (let v = 1; v <= n; v++) first ^= v;
  for (let i = 1; i < encoded.length; i += 2) first ^= encoded[i];
  const seen = new Array(n + 1).fill(false);
  let current = first;
  for (let i = 0; i <= encoded.length; i++) {
    if (current < 1 || current > n || seen[current]) return 'encoded must come from a permutation of 1..n.';
    seen[current] = true;
    if (i < encoded.length) current ^= encoded[i];
  }
  return null;
}

