function decode(encoded) {
  // Try every possible first value and keep the one that rebuilds a permutation of 1..n.
  const n = encoded.length + 1;
  for (let start = 1; start <= n; start++) {
    const candidate = [start];
    for (const e of encoded) candidate.push(candidate[candidate.length - 1] ^ e);
    const sorted = [...candidate].sort((a, b) => a - b);
    if (sorted.every((v, i) => v === i + 1)) return candidate;
  }
  return [];
}

