function generate(rand, size) {
  const n = size === 'small' ? 3 + 2 * Math.floor(rand() * 7) : 1501 + 2 * Math.floor(rand() * 251);
  const perm = Array.from({ length: n }, (_, i) => i + 1);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [perm[i], perm[j]] = [perm[j], perm[i]];
  }
  if (size === 'small' && rand() < 0.15) perm.sort((a, b) => (rand() < 0.5 ? a - b : b - a));
  return [perm.slice(1).map((value, i) => perm[i] ^ value)];
}
